const providerBadges = (provider: LlmProvider) => {
	const badges: string[] = [];
	if (envProviders.includes(provider)) {
		badges.push('ENV');
	}
	if (configProviders.some((c) => c.provider === provider)) {
		badges.push('nao_config.yaml');
	}
	return badges;
};

